pdf/10.1177/17456916231181102", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1177/17456916231181102", "doi": "https://doi.org/10.1177/17456916231181102", "is_oa": true, "landing_page_url": "https://doi.org/10.1177/17456916231181102", "pdf_url": "https://journals.sagepub.com/doi/pdf/10.1177/17456916231181102", "source": {"id": "https://openalex.org/S27228949", "display_name": "Perspectives on Psychological Science", "issn_l": "1745-6916", "issn": ["1745-6916", "1745-6924"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["cwts-core", "dongbi-a", "erih-plus", "jufo-3", "ki-jl-2", "medline", "norway-2", "poland-200", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310320017", "host_organization_name": "SAGE Publishing", "host_organization_lineage": ["https://openalex.org/P4310320017"], "host_organization_lineage_names": ["SAGE Publishing"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Perspectives on Psychological Science", "raw_type": "journal-article"}, "abstract": "Artificial intelligence (AI) has the potential to improve human decision-making by providing decision recommendations and problem-relevant information to assist human decision-makers. However, the full realization of the potential of human-AI collaboration continues to face several challenges. First, the conditions that support complementarity (i.e., situations in which the performance of a human with AI assistance exceeds the performance of an unassisted human or the AI in isolation) must be understood. This task requires humans to be able to recognize situations in which the AI should be leveraged and to develop new AI systems that can learn to complement the human decision-maker. Second, human mental models of the AI, which contain both expectations of the AI and reliance strategies, must be accurately assessed. Third, the effects of different design choices for human-AI interaction must be understood, including both the timing of AI assistance and the amount of model information that should be presented to the human decision-maker to avoid cognitive overload and ineffective reliance strategies. In response to each of these three challenges, we present an interdisciplinary perspective based on recent empirical and theoretical findings and discuss new research directions."}]", "excerpt_truncated": true, "source_sha256": "a491d80bdfebbb6a9b24bb001c0f515d59ee354008e57cc68bdbb4db9af57775", "verification_required": true, "topic_domain": "unrecognized_reasoning_limits", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s10462-018-9646-y", "doi:10.1007/s10462-018-9646-y.pdf", "doi:10.1177/17456916231181102", "openalex:W2883445328"], "source_candidates": ["https://doi.org/10.1007/s10462-018-9646-y", "https://link.springer.com/content/pdf/10.1007/s10462-018-9646-y.pdf", "https://doi.org/10.1177/17456916231181102", "https://journals.sagepub.com/doi/pdf/10.1177/17456916231181102"], "source_candidate_identities": {}}
